#!/usr/bin/env python3
import base64
from itertools import cycle
import string
from rfc8032 import point_add, point_compress, point_decompress, point_equal, point_mul, G

# Helper functions from handout
topoint = lambda n: point_mul(n, G)
negate = lambda p: (p[0], -p[1], -p[2], p[3])

def catch(f, g, ty=Exception):
    try:
        return f()
    except ty as e:
        return g(e)

def frompoint(p):
    return catch(lambda: filter(lambda x: point_equal(p,topoint(x)), range(256)).__next__(), lambda _: None, StopIteration)

def decrypt_char(key_byte, ct_point):
    """Decrypt a single character given a key byte and ciphertext point"""
    pt_point = point_add(negate(topoint(key_byte)), ct_point)
    return frompoint(pt_point)

def is_printable(char):
    """Check if a character value is printable ASCII"""
    return char is not None and 32 <= char <= 126

# Known key bytes and their positions
known_key = {
    0: 0xee,
    1: 0xb7,
    2: 0xca,
    3: 0xc7,
    4: 0x75
}

# Load ciphertext
with open('ciphertext', 'rb') as f:
    ctxt = f.read()

# Parse points from ciphertext
points = [point_decompress(base64.b64decode(p)) for p in ctxt.split(b';')]

# Group points by their position in the 12-byte cycle
point_groups = [[] for _ in range(12)]
for i, point in enumerate(points):
    point_groups[i % 12].append((i, point))

def try_key_byte(pos, point_group):
    """Try possible key bytes for a position"""
    valid_bytes = []
    for key_byte in range(256):
        valid = True
        chars = []
        for _, pt in point_group:
            char = decrypt_char(key_byte, pt)
            if not is_printable(char):
                valid = False
                break
            chars.append(chr(char))
        if valid:
            print(f"Position {pos}: Key byte 0x{key_byte:02x} produces: {''.join(chars[:20])}")
            valid_bytes.append(key_byte)
    return valid_bytes

def try_find_key():
    """Try to find the complete key"""
    key = [None] * 12

    # Set known key bytes
    for pos, byte in known_key.items():
        key[pos] = byte

    # Try to find remaining key bytes
    for pos in range(12):
        if key[pos] is not None:
            continue

        print(f"\nAnalyzing position {pos}...")
        valid_bytes = try_key_byte(pos, point_groups[pos])

        if len(valid_bytes) == 1:
            key[pos] = valid_bytes[0]
            print(f"Found unique key byte for position {pos}: 0x{valid_bytes[0]:02x}")
        elif len(valid_bytes) > 1:
            print(f"Multiple possibilities for position {pos}: {[hex(b) for b in valid_bytes]}")

    return key

def decrypt_with_key(key):
    """Decrypt the message with a given key"""
    result = []
    for (pos, point) in enumerate(points):
        key_byte = key[pos % 12]
        if key_byte is None:
            result.append('?')
            continue
        char = decrypt_char(key_byte, point)
        if char is None:
            result.append('?')
        else:
            result.append(chr(char))
    return ''.join(result)

# Find and verify the key
key = try_find_key()
print("\nFound key:", [hex(k) if k is not None else None for k in key])

# Decrypt with the found key
decrypted = decrypt_with_key(key)
print("\nDecrypted text sample (first 200 chars):")
print(decrypted[:200])

