import string
from rfc8032 import point_add, point_compress, point_decompress, point_equal, point_mul, G

# Helper functions from handout
topoint = lambda n: point_mul(n, G)
negate = lambda p: (p[0], -p[1], -p[2], p[3])

def catch(f, g, ty=Exception):
    try:
        return f()
    except ty as e:
        return g(e)

def frompoint(p):
    return catch(lambda: filter(lambda x: point_equal(p,topoint(x)), range(256)).__next__(), lambda _: None, StopIteration)

def decrypt_char(key_byte, ct_point):
    """Decrypt a single character given a key byte and ciphertext point"""
    pt_point = point_add(negate(topoint(key_byte)), ct_point)
    return frompoint(pt_point)

def is_printable(char):
    """Check if a character value is printable ASCII"""
    return char is not None and 32 <= char <= 126

# Known key bytes and their positions
known_key = {
    0: 0xee,
    1: 0xb7,
    2: 0xca,
    3: 0xc7,
    4: 0x75
}

# Load ciphertext
with open('ciphertext', 'rb') as f:
    ctxt = f.read()

# Parse points from ciphertext
points = [point_decompress(base64.b64decode(p)) for p in ctxt.split(b';')]

# Group points by their position in the 12-byte cycle
point_groups = [[] for _ in range(12)]
for i, point in enumerate(points):
    point_groups[i % 12].append((i, point))

def try_key_byte(pos, points_subset, expected_text=None):
    """Try possible key bytes for a position with expected text hint"""
    valid_bytes = []

    # If we have expected text, use it to narrow down possibilities
    if expected_text and len(points_subset) >= len(expected_text):
        for key_byte in range(256):
            matches = True
            for i, (_, pt) in enumerate(points_subset[:len(expected_text)]):
                char = decrypt_char(key_byte, pt)
                if char is None or chr(char) != expected_text[i]:
                    matches = False
                    break
            if matches:
                valid_bytes.append(key_byte)
        return valid_bytes

    # Otherwise look for printable ASCII
    for key_byte in range(256):
        valid = True
        chars = []
        for _, pt in points_subset[:10]:  # Check first few characters
            char = decrypt_char(key_byte, pt)
            if not is_printable(char):
                valid = False
                break
            chars.append(chr(char))
        if valid:
            print(f"Position {pos}: Key byte 0x{key_byte:02x} produces: {''.join(chars)}")
            valid_bytes.append(key_byte)
    return valid_bytes

def test_key_combination(key_bytes):
    """Test a combination of key bytes for valid plaintext"""
    test_text = ""
    for i, point in enumerate(points[:100]):  # Test first 100 characters
        key_byte = key_bytes[i % 12]
        if key_byte is None:
            test_text += '?'
            continue
        char = decrypt_char(key_byte, point)
        if char is None or not is_printable(char):
            return False
        test_text += chr(char)

    # Check if it starts with "flag{" and contains mostly English text
    if not test_text.startswith("flag{"):
        return False

    # Count common English characters
    english_chars = set("etaoinshrdlcumwfgypbvkjxqz ETAOINSHRDLCUMWFGYPBVKJXQZ")
    english_char_count = sum(1 for c in test_text if c in english_chars)
    if english_char_count / len(test_text) < 0.7:  # At least 70% should be common English chars
        return False

    print("\nPossible valid key found!")
    print("Key:", [hex(k) if k is not None else None for k in key_bytes])
    print("Sample text:", test_text[:200])
    return True

def find_full_key():
    """Find the complete 12-byte key"""
    key = [None] * 12

    # Set known key bytes
    for pos, byte in known_key.items():
        key[pos] = byte

    # First pass: get candidates for each position
    candidates = {}
    for pos in range(12):
        if key[pos] is not None:
            candidates[pos] = [key[pos]]
            continue

        print(f"\nAnalyzing position {pos}...")
        # Try position 5 with expected 'f' if it's the right offset
        if pos == 5 and len(points) > pos:
            valid_bytes = try_key_byte(pos, point_groups[pos], "f")
        else:
            valid_bytes = try_key_byte(pos, point_groups[pos])

        if valid_bytes:
            candidates[pos] = valid_bytes
            print(f"Found {len(valid_bytes)} candidates for position {pos}")
        else:
            candidates[pos] = list(range(256))  # If no clear candidates, try all bytes

    # Try combinations of candidates
    for pos5_key in candidates.get(5, [None]):
        if pos5_key is not None:
            key[5] = pos5_key
            for pos6_key in candidates.get(6, [None]):
                if pos6_key is not None:
                    key[6] = pos6_key
                    for pos7_key in candidates.get(7, [None]):
                        key[7] = pos7_key
                        for pos8_key in candidates.get(8, [None]):
                            key[8] = pos8_key
                            for pos9_key in candidates.get(9, [None]):
                                key[9] = pos9_key
                                for pos10_key in candidates.get(10, [None]):
                                    key[10] = pos10_key
                                    for pos11_key in candidates.get(11, [None]):
                                        key[11] = pos11_key
                                        if test_key_combination(key):
                                            return key

    return key

# Find and verify the key
key = find_full_key()
print("\nFinal key:", [hex(k) if k is not None else None for k in key])

# Decrypt the full message
decrypted = ""
for i, point in enumerate(points):
    key_byte = key[i % 12]
    if key_byte is None:
        decrypted += '?'
        continue
    char = decrypt_char(key_byte, point)
    if char is None:
        decrypted += '?'
    else:
        decrypted += chr(char)

print("\nFull decrypted text:")
print(decrypted[:1000])

