import base64
from itertools import product
import string
from rfc8032 import point_add, point_compress, point_decompress, point_equal, point_mul, G

# Helper functions from handout
topoint = lambda n: point_mul(n, G)
negate = lambda p: (p[0], -p[1], -p[2], p[3])

def catch(f, g, ty=Exception):
    try:
        return f()
    except ty as e:
        return g(e)

def frompoint(p):
    return catch(lambda: filter(lambda x: point_equal(p,topoint(x)), range(256)).__next__(), lambda _: None, StopIteration)

def decrypt_char(key_byte, ct_point):
    """Decrypt a single character given a key byte and ciphertext point"""
    pt_point = point_add(negate(topoint(key_byte)), ct_point)
    return frompoint(pt_point)

def is_printable(char):
    """Check if a character value is printable ASCII"""
    return char is not None and 32 <= char <= 126

# Known key bytes and their positions
known_key = {
    0: 0xee,  # 'f'
    1: 0xb7,  # 'l'
    2: 0xca,  # 'a'
    3: 0xc7,  # 'g'
    4: 0x75   # '{'
}

# Load ciphertext
with open('ciphertext', 'rb') as f:
    ctxt = f.read()

# Parse points from ciphertext
points = [point_decompress(base64.b64decode(p)) for p in ctxt.split(b';')]

def find_key_for_text(point, expected_char):
    """Find key byte that produces expected character"""
    if expected_char is None:
        return set(k for k in range(256) if is_printable(decrypt_char(k, point)))
    char_val = ord(expected_char)
    result = set()
    for k in range(256):
        if decrypt_char(k, point) == char_val:
            result.add(k)
    return result

# Common English words that might appear after "flag{"
common_words = [
    "authorized",
    "memorizing",
    "analyzing",
    "optimizing",
    "utilizing",
    "recognize",
    "realized",
]

def test_key_combination(key_bytes):
    """Test if a key combination produces readable text"""
    test_text = ""
    valid_chars = 0

    # Test first few blocks
    for i, point in enumerate(points[:48]):
        key_byte = key_bytes[i % 12]
        char = decrypt_char(key_byte, point)
        if char is None or not is_printable(char):
            return False, ""
        test_text += chr(char)
        if chr(char) in string.printable:
            valid_chars += 1

    # Check if it produces sensible text
    if not test_text.startswith("flag{"):
        return False, ""

    # Calculate ratio of valid printable characters
