def recover_key_byte(cipher_point, known_char):
    target_point = topoint(ord(known_char))
    for k in range(256):
        key_point = topoint(k)
        test_point = point_add(key_point, target_point)
        if point_equal(test_point, cipher_point):
            return k
    return None

def try_decrypt_byte(key_byte, cipher_point):
    if key_byte is None:
        return None
    dec = frompoint(point_add(negate(topoint(key_byte)), cipher_point))
    if dec is None:
        return None
    return chr(dec)

def is_printable(text):
    return all(c in string.printable for c in text)

def main():
    # Read ciphertext
    with open('ciphertext', 'rb') as f:
