import base64
from itertools import product
import string

from rfc8032 import point_add, point_compress, point_decompress, point_equal, point_mul, G

def catch(f, g, ty=Exception):
    try:
        return f()
    except ty as e:
        return g(e)

topoint = lambda n: point_mul(n, G)
frompoint = lambda p: catch(lambda: filter(lambda x: point_equal(p,topoint(x)), range(256)).__next__(), lambda _: None, StopIteration)

negate = lambda p: (p[0], -p[1], -p[2], p[3])

def try_decrypt_byte(key_byte, cipher_point):
    if key_byte is None:
        return None
    dec = frompoint(point_add(negate(topoint(key_byte)), cipher_point))
    if dec is None:
        return None
    return chr(dec) if dec < 128 else None

def is_valid_flag_char(c):
    return c in string.ascii_letters + string.digits + "_{}"

def main():
    # Read ciphertext
    with open('ciphertext', 'rb') as f:
        ctxt = f.read().strip()

    points = [point_decompress(base64.b64decode(p)) for p in ctxt.split(b';')]

    # Initial key based on known pattern
    base_key = [0xee, 0xb7, 0xca, 0xc7, 0x75]

    # Fixed offset patterns to try
    key_patterns = [
        # Pattern 1 - original
        [0x9b, 0xee, 0xea, 0x9a, 0x5b, 0x92, 0x18],
        # Pattern 2 - adjusted
        [0x9c, 0xef, 0xe9, 0x9b, 0x5c, 0x93, 0x17],
        # Pattern 3 - shifted down
        [0x9a, 0xed, 0xeb, 0x99, 0x5a, 0x91, 0x19],
        # Pattern 4 - shifted up
        [0x9d, 0xf0, 0xe8, 0x9c, 0x5d, 0x94, 0x16]
    ]

    print("Testing key patterns...")

    for pattern_num, extra_key in enumerate(key_patterns, 1):
        key = base_key + extra_key
        print(f"\nTrying pattern {pattern_num} with key:", [hex(k) for k in key])

        # Decrypt and look for flag pattern
        decrypted = ""
        for i, point in enumerate(points):
            dec = try_decrypt_byte(key[i % 12], point)
            if dec is None:
                dec = '?'
            decrypted += dec

            # Look for valid flag pattern
            if len(decrypted) > 5:
                flag_start = decrypted.find('flag{')
                if flag_start != -1:
                    # Try to find complete flag
                    for j in range(flag_start + 5, len(decrypted)):
                        if decrypted[j] == '}':
                            potential_flag = decrypted[flag_start:j + 1]
                            if all(is_valid_flag_char(c) for c in potential_flag):
                                print("\nFound potential flag:", potential_flag)
                                print("Flag characters are all valid!")
                                if len(potential_flag) > 10:  # Reasonable flag length
                                    return

            # Only try first 100 chars for each pattern
            if i > 100:
                break

        print("Decrypted start:", decrypted[:50].replace('?', '▯'))

if __name__ == '__main__':
    main()

